def get_divisors(n):
    divs = set()
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    return sorted(list(divs))

def check_condition(n):
    divisors = get_divisors(n)
    tau_n = len(divisors)

    if tau_n < 5:
        return None, None, None, False

    # a = 2nd smallest divisor (index 1)
    # b = 3rd smallest divisor (index 2)
    # c = 5th smallest divisor (index 4)

    if len(divisors) < 5:
        # This shouldn't happen if tau_n >= 5, but as a safeguard.
        return None, None, None, False

    a = divisors[1]
    b = divisors[2]
    c = divisors[4]

    # Check the simplified equation: ab + ac + bc = n
    LHS = a*b + a*c + b*c
    RHS = n

    return a, b, c, (LHS == RHS)

results = []
# Checking up to n=50 to gather initial data
for n in range(1, 51):
    a, b, c, passed = check_condition(n)

    if a is not None:
        results.append({
            'n': n,
            'tau(n)': len(get_divisors(n)),
            'a': a,
            'b': b,
            'c': c,
            'pass': passed
        })

print("--- Results up to n=50 ---")
for res in results:
    print(f"n={res['n']}, tau(n)={res['tau(n)']}, a={res['a']}, b={res['b']}, c={res['c']}, Pass Check: {res['pass']}")

